// Top-down objects are vectors so their contents can change as you prepare.
let artSequence=0;
function objectArt(item,fill){
 const luxuryTiles={'Arborio rice':[0,0],'Vegetable stock':[1,0],'Black truffle':[2,0],'Cooked lobster':[0,1],Saffron:[1,1],Butter:[2,1],'Dark chocolate':[0,2],Eggs:[1,2],Flour:[2,2]};
 const luxuryDishes={'Finished risotto':[0,0],'Finished lobster':[1,0],'Finished fondant':[2,0],Ramekin:[0,1],'Mixing bowl':[1,1],'Fine plate':[2,1]};
 if(luxuryTiles[item]||luxuryDishes[item]){const ing=!!luxuryTiles[item],[x,y]=luxuryTiles[item]||luxuryDishes[item];return `<span class="food-sprite ${ing?'luxury-ingredient':'luxury-dish'}" style="--sx:${x*50}%;--sy:${y*(ing?50:100)}%" aria-hidden="true"></span>`;}
 if(item==='Cream')return objectArt('Milk');
 const chefTiles={'Pizza dough':[0,0],'Tomato sauce':[1,0],Mozzarella:[2,0],Basil:[0,1],Penne:[1,1],Mushrooms:[2,1],'Olive oil':[0,2],Garlic:[1,2],Parmesan:[2,2]};
 const dishTiles={'Finished pizza':[0,0],'Finished pasta':[1,0],'Finished melt':[2,0],'Frying pan':[0,1],'Cooking pot':[1,1],'Pizza tray':[2,1]};
 if(chefTiles[item]||dishTiles[item]){const chef=!!chefTiles[item],[x,y]=(chefTiles[item]||dishTiles[item]);return `<span class="food-sprite ${chef?'chef-sprite':'restaurant-sprite'}" style="--sx:${x*50}%;--sy:${y*(chef?50:100)}%" aria-hidden="true"></span>`;}

 const tiles={Bread:[0,0],Lettuce:[1,0],Tomato:[2,0],Cheese:[0,1],Croissant:[1,1],Plate:[2,1]};
 if(tiles[item]){const [x,y]=tiles[item];return `<span class="food-sprite food-${item.toLowerCase()}" style="--sx:${x*50}%;--sy:${y*100}%" aria-hidden="true"></span>`;}

 const asset=item==='Salt'?'salt':/Coffee powder|Instant coffee|Ground coffee/.test(item)?'coffee':item==='Cup'?'cup':/milk/i.test(item)?'milk':/water|Espresso|Pour coffee/.test(item)?'kettle':item==='Sugar'?'sugar':/Tea|infuser/.test(item)?'infuser':item==='Stir'?'spoon':null;
 if(asset)return `<span class="photo-object photo-${asset} ${item==='Green tea infuser'?'green-leaves':''}"><img src="assets/real-${asset}.png" alt="" draggable="false">${asset==='cup'&&fill?`<i class="real-liquid" style="--tea-color:${fill}"></i>`:''}</span>`;

 const uid="material-"+(artSequence++);
 let shape='';
 const bowl=(color)=>`<circle cx="60" cy="60" r="43" fill="#f6efda" stroke="#315b70" stroke-width="5"/><circle cx="60" cy="60" r="34" fill="${color}"/><path d="M37 36Q57 22 79 37" fill="none" stroke="#fff" opacity=".5" stroke-width="4"/>`;
 if(item==='Cup')shape=`<rect x="94" y="45" width="22" height="30" rx="10" fill="#ede5cc" stroke="#315b70" stroke-width="5"/>${bowl(fill||'#e3d9bf')}`;
 else if(/milk/i.test(item))shape=`<path d="M89 42Q120 37 110 70Q104 82 90 76" fill="none" stroke="#315b70" stroke-width="8"/><path d="M38 24L22 14L28 44C9 96 97 112 99 60Q98 20 38 24" fill="#f4eedc" stroke="#315b70" stroke-width="4"/><ellipse cx="61" cy="54" rx="28" ry="24" fill="#fffbea"/><path d="M34 34L24 22" stroke="#fff" stroke-width="4"/>`;
 else if(/water|Espresso|Pour coffee/.test(item))shape=`<path d="M35 31Q58 1 86 32" fill="none" stroke="#2c4149" stroke-width="10"/><path d="M32 49L5 34L14 70L36 81" fill="#aab9b6" stroke="#435d62" stroke-width="3"/><circle cx="65" cy="66" r="38" fill="#bbc6bf" stroke="#405b60" stroke-width="4"/><circle cx="65" cy="64" r="27" fill="#e1e4d8" stroke="#83938f" stroke-width="3"/><circle cx="65" cy="64" r="8" fill="#355363"/>`;
 else if(item==='Sugar')shape=bowl('#fff7df')+Array.from({length:12},(_,i)=>`<rect x="${36+i%4*12}" y="${36+Math.floor(i/4)*15}" width="10" height="12" rx="2" fill="#fffdf4" stroke="#d8c9ad"/>`).join('');
 else if(/Tea|infuser/.test(item))shape=`<path d="M60 18L60 1" stroke="#acb5b0" stroke-width="3"/><circle cx="60" cy="63" r="39" fill="#827d61" stroke="#d8ddd1" stroke-width="5"/>`+Array.from({length:32},(_,i)=>`<ellipse cx="${34+(i*17)%53}" cy="${35+(i*11)%54}" rx="3" ry="5" fill="${i%2?'#364739':'#68704a'}" transform="rotate(${i*20} 60 63)"/>`).join('')+`<circle cx="60" cy="63" r="30" fill="none" stroke="#d7d9be" stroke-dasharray="2 4" stroke-width="30" opacity=".22"/>`;
 else if(item==='Stir')shape='<rect x="54" y="42" width="12" height="72" rx="6" fill="#b9c7c2" stroke="#6b817f" stroke-width="2"/><ellipse cx="60" cy="27" rx="18" ry="25" fill="#e2e7dd" stroke="#6b817f" stroke-width="3"/>';
 else if(item==='Brew')shape='<circle cx="60" cy="60" r="38" fill="#eee5ce" stroke="#315b70" stroke-width="5"/><path d="M60 33V60L79 71" fill="none" stroke="#315b70" stroke-width="5"/>';
 else if(item==='Plate')shape=bowl('#eee7d7');
 else shape=bowl('#ece0bc')+`<text x="60" y="80" text-anchor="middle" font-size="51">${ICONS[item]||'✦'}</text>`;
 shape=shape.replaceAll('fill="#f6efda"',`fill="url(#${uid}-ceramic)"`).replaceAll('fill="#f4eedc"',`fill="url(#${uid}-ceramic)"`).replaceAll('fill="#bbc6bf"',`fill="url(#${uid}-steel)"`).replaceAll('fill="#e1e4d8"',`fill="url(#${uid}-steel)"`).replaceAll('fill="#b9c7c2"',`fill="url(#${uid}-steel)"`);
 return `<svg viewBox="0 0 120 120" aria-hidden="true"><defs><radialGradient id="${uid}-ceramic" cx="32%" cy="25%" r="80%"><stop stop-color="#fffdf0"/><stop offset=".65" stop-color="#eee4cd"/><stop offset=".87" stop-color="#c8b897"/><stop offset="1" stop-color="#f6efd9"/></radialGradient><linearGradient id="${uid}-steel" x1="0" y1="0" x2="1" y2=".7"><stop stop-color="#637f80"/><stop offset=".25" stop-color="#f4f1da"/><stop offset=".43" stop-color="#a5bbb6"/><stop offset=".54" stop-color="#f6f8ec"/><stop offset=".8" stop-color="#809894"/><stop offset="1" stop-color="#344f56"/></linearGradient></defs>${shape}</svg>`;
}
const AUTOMATIC_STEPS={"Soften garlic":{"seconds": 3, "title": "Softening garlic in butter…", "note": "Gently cooking without browning."},"Toast rice":{"seconds": 3, "title": "Toasting the rice…", "note": "Coating each grain in butter."},"Simmer risotto":{"seconds": 10, "title": "Adding stock, stirring, simmering…", "note": "Adding stock a ladle at a time until creamy. Game time is shortened."},"Finish risotto":{"seconds": 3, "title": "Finishing off the heat…", "note": "Stirring in parmesan."},"Reduce saffron sauce":{"seconds": 6, "title": "Infusing the saffron cream…", "note": "Pasta is set aside while the sauce thickens."},"Warm lobster":{"seconds": 5, "title": "Warming lobster and tossing pasta…", "note": "Prepared cooked lobster warms gently in the sauce."},"Melt chocolate":{"seconds": 5, "title": "Melting chocolate and butter…", "note": "Melting gently, then cooling before adding eggs."},"Whisk mixture":{"seconds": 3, "title": "Whisking until glossy…", "note": "Combining eggs and sugar with cooled chocolate."},"Fold batter":{"seconds": 3, "title": "Folding in flour…", "note": "Gently folding until combined."},"Bake fondant":{"seconds": 9, "title": "Baking and resting the fondant…", "note": "Greasing and filling the ramekin, baking and resting. Game time is shortened."},
'Bake pizza':{seconds:6,title:'Pizza in the oven…',note:'Baking the crust and melting the mozzarella. 6 seconds in play; actual oven times vary.'},
'Boil pasta':{seconds:5,title:'Pasta is bubbling…',note:'Cooking the penne until al dente. Game time is shortened.'},
'Drain pasta':{seconds:2,title:'Draining the pasta…',note:'Carefully lifting out the pasta and draining the cooking water.'},
'Simmer sauce':{seconds:4,title:'Tossing in warm sauce…',note:'Heating the prepared tomato sauce and coating the penne.'},
'Sauté mushrooms':{seconds:4,title:'Mushrooms are sizzling…',note:'Cooking the mushrooms in olive oil until tender.'},
'Assemble melt':{seconds:2,title:'Assembling the mushroom melt…',note:'Layering the cooked mushrooms and cheese between the bread slices.'},
'Grill melt':{seconds:5,title:'Grilling both sides…',note:'Turning the sandwich automatically until golden and the cheese melts.'},'Extract espresso':{seconds:3,title:'Extracting espresso…',note:'The café machine tamps the grounds and extracts a fresh shot into your cup.'},'Cool water':{seconds:3,title:'Cooling the water…',note:'Letting the boiled water cool to around 80°C before adding green tea.'},'Brew green tea':{seconds:2,title:'Gently steeping green tea…',note:'A shorter steep keeps the flavour light. 2 seconds in play · about 2 minutes in real life.'},'Dissolve coffee':{seconds:2,title:'Dissolving the coffee…',note:'Stirring instant coffee into hot water — no machine needed.'},'Brew':{seconds:4,title:'Brew time…',note:'Letting the tea leaves release their flavour.'},'Remove infuser':{seconds:1.4,title:'Lifting out the infuser…',note:'One last drip, then it is ready for the next ingredient.'},'Stir':{seconds:1.8,title:'Stirring gently…',note:'Bringing everything together.'},'Heat pastry':{seconds:3,title:'Warming the pastry…',note:'A little warmth makes all the difference.'}};
let recipeViewFor=null;
function autoActionStatus(o){const a=AUTOMATIC_STEPS[o.action];return `<div class="auto-status ${a?'automatic':''}"><span class="eyebrow">${a?'AUTOMATIC STEP · PLEASE WAIT':'ADDING INGREDIENT'}</span><div class="auto-title"><b>${a?a.title:'Preparing…'}</b><span id="auto-countdown">${Math.max(1,Math.ceil(o.actionLeft))}s</span></div><div class="brew-track"><i id="action-progress" style="width:${100*(1-o.actionLeft/o.actionTotal)}%"></i></div><small>${a?a.note:'Setting everything in place.'}</small>${o.action==='Brew'?'<small class="brew-note">4 seconds in play · 3–5 minutes in real life</small>':''}</div>`}

function ingredientChoices(o){
 if(!o.choices){const r=recipe(o),distractors=r.level>=3?['Sugar','Instant coffee','Garlic']:r.steps.includes('Plate')?['Salt','Instant coffee','Sugar']:['Salt','Instant coffee','Milk','Sugar','Tea infuser','Green tea infuser'];const items=[...new Set([...r.steps,...distractors])].filter(s=>!AUTOMATIC_STEPS[s]);for(let i=items.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[items[i],items[j]]=[items[j],items[i]]}o.choices=items;}
 return o.choices.filter(s=>!AUTOMATIC_STEPS[s]);
}
function preparation(o){
 const r=recipe(o),done=o.step===r.steps.length,tea=r.steps.some(s=>s.includes('tea infuser')||s==='Tea infuser'),green=r.id==='green-tea',has=s=>r.steps.slice(0,o.step).includes(s),food=['sandwich','cheese-tomato','croissant','pizza','pasta','mushroom-melt','truffle-risotto','lobster-pasta','chocolate-fondant'].includes(r.id),open=recipeViewFor===o.id;
 const color=has('Milk')||has('Steamed milk')?(tea?'#d0a16a':'#a87950'):has('Hot milk')?'#805039':has('Hot water')||has('Espresso')||has('Extract espresso')?(green?(has('Green tea infuser')?'#bbc76e':'#d4dfd5'):tea?'#a86b26':'#402413'):null;
 const placed=has('Cup')||has('Plate')||has('Pizza tray')||has('Cooking pot')||has('Frying pan')||has('Mixing bowl');
 const visual=food?foodArt(r,o.step):objectArt('Cup',color);
 const family=o.group?state.orders.filter(x=>x.group===o.group):[],allReady=family.length&&family.every(x=>x.step===recipe(x).steps.length&&!x.action);
 const readyButton=family.length?allReady?`<button class="primary" data-action="serve" data-id="${o.id}">Serve all ${family.length} items together →</button>`:`<button class="primary" data-action="next-family" data-id="${o.group}">Set aside & prepare next →</button>`:`<button class="primary" data-action="serve" data-id="${o.id}">Serve to ${esc(o.name)} →</button>`;

 return `<main class="prep-screen challenge-screen ${r.level>=4?'luxury-kitchen':''} ${busy?'working':''} ${['Brew','Brew green tea'].includes(o.action)?'is-brewing':''} ${o.action==='Remove infuser'?'is-lifting':''}"><header class="prep-header"><button data-action="counter">← Customer</button><div><span class="eyebrow">ORDER FOR ${esc(o.name)}</span><b>${r.name}</b></div><div class="prep-score">$${state.cash} · ${state.xp} XP<button data-action="pause">Ⅱ Pause</button></div></header>${family.length?`<nav class="family-prep-queue" aria-label="Group preparation queue"><span>ONE ORDER · ${family.filter(x=>x.step===recipe(x).steps.length).length}/${family.length} ready</span>${family.map((x,i)=>`<button class="${x.id===o.id?'active':''}" data-action="select" data-id="${x.id}">${i+1}. ${recipe(x).name} ${x.step===recipe(x).steps.length?'✓':''}</button>`).join('')}<small>Shared timer · serve together</small></nav>`:''}<div class="challenge-workspace"><aside class="ingredient-side"><div class="recipe-help"><button class="recipe-toggle" data-recipe-toggle aria-expanded="${open}" aria-controls="recipe-popover">View recipe <span aria-hidden="true">▤</span></button><small>Confused about the recipe?</small></div><div class="ingredient-intro"><span class="eyebrow">YOUR INGREDIENTS</span><p>Choose carefully. Some ingredients don't belong.</p></div><div class="ingredient-grid">${ingredientChoices(o).map(s=>prepTool(s,done)).join('')}</div><p class="challenge-rules">Wrong ingredient? Start over.<br>The timer keeps running.</p></aside><section class="large-prep-area" aria-label="Preparation area"><div class="challenge-status"><span class="eyebrow">${done?'READY TO SERVE':busy?'MAKING YOUR ORDER':'MAKE IT FROM MEMORY'}</span><span id="prep-clock" class="timer-badge">${timeText(o)}</span></div><div id="board" aria-disabled="${busy||done}" class="top-board ${placed?'has-cup':''} ${o.mistake?'mistake-board':''}" role="button" tabindex="0" aria-label="Preparation board; place selected ingredient"><div class="woven-mat" aria-hidden="true"></div>${placed?`<div class="cup-art ${food?'food-assembly':''} ${color?'filled':''}">${visual}${tea&&(has('Tea infuser')||has('Green tea infuser'))&&!has('Remove infuser')?'<div class="infuser-in-cup">'+objectArt(green?'Green tea infuser':'Tea infuser')+'</div>':''}${color&&!food?'<div class="tea-steam" aria-hidden="true"><i></i><i></i><i></i></div>':''}${has('Milk foam')?'<div class="foam">♡</div>':''}${has('Marshmallow')?'<div class="foam">☁</div>':''}</div>`:''}${busy&&!AUTOMATIC_STEPS[o.action]?'<div class="ingredient-motion '+(['Stir','Dissolve coffee'].includes(o.action)?'stirring':'pouring')+'">'+objectArt(o.action==='Dissolve coffee'?'Stir':o.action)+'</div>':''}</div><div class="prep-action" aria-live="polite">${done?readyButton:busy?autoActionStatus(o):o.mistake?`<p class="mistake-message">${esc(o.mistake)}</p>`:`<span>Drag your chosen item to the ${food?(r.level>=3?'preparation area':'plate'):'cup'}<br><small>Or select it, then tap the preparation area</small></span>`}</div><p class="reward-note">${state.relaxed?'Relaxed mode · timer and rewards stay steady':'Faster service earns more XP and tips'}</p></section></div>${open?recipePopover(o):''}${modal?modalHTML():''}</main>`;
}
function prepTool(s,done){return `<button class="prep-tool" data-ingredient="${s}" aria-label="${s}" ${busy||done?'disabled':''}>${objectArt(s)}<span>${s}</span></button>`}
function recipePopover(o){const r=recipe(o);return `<div class="recipe-scrim"><section id="recipe-popover" class="recipe-popover" role="dialog" aria-modal="true" aria-label="Order recipe"><div class="row"><span class="eyebrow">A LITTLE HELP</span><button data-recipe-close aria-label="Close recipe">✕</button></div><h2>${r.name}</h2><p>${state.relaxed?'Relaxed mode · take your time.':'Your customer is waiting — the timer keeps running.'}</p><small data-time="${o.id}">${timeText(o)}</small>${r.note?'<p>'+esc(r.note)+'</p>':r.id==='coffee'?'<p>Set down a cup, add ground coffee to the machine, and let it extract automatically. Add hot water to make an Americano.</p>':r.id==='green-tea'?'<p>Pour hot water into the empty cup and let it cool to around 80°C. Add the green tea infuser, steep for about 2 minutes, then remove it. No milk or sugar.</p>':r.steps.includes('Instant coffee')?'<p>Use soluble instant coffee, not ground coffee. Dissolve it in hot water, then add milk or sugar only when ordered.</p>':r.steps.includes('Tea infuser')?'<p>Steep black tea in freshly boiled water, lift out the infuser, then add only the requested milk or sugar.</p>':''}<ol>${r.steps.map((s,i)=>`<li class="${i<o.step?'complete':i===o.step?'current':''}">${objectArt(s)}<span>${s}${AUTOMATIC_STEPS[s]?'<small class="auto-label">Automatic</small>':''}</span>${i<o.step?'<b>✓</b>':''}</li>`).join('')}</ol><button class="primary wide" data-recipe-close>Back to preparing →</button></section></div>`}

function drinkPreview(r){if(['sandwich','cheese-tomato','croissant','pizza','pasta','mushroom-melt','truffle-risotto','lobster-pasta','chocolate-fondant'].includes(r.id))return `<span class="food-preview">${foodArt(r,r.steps.length)}</span>`;const milk=r.steps.some(s=>/milk/i.test(s));const color=r.id==='green-tea'?'#bbc76e':r.steps.includes('Tea infuser')?(milk?'#d0a16a':'#a86b26'):(milk?'#a87950':'#402413');return objectArt('Cup',color);}

function foodArt(r,step){if(['truffle-risotto','lobster-pasta','chocolate-fondant'].includes(r.id))return luxuryFoodArt(r,step);if(['pizza','pasta','mushroom-melt','truffle-risotto','lobster-pasta','chocolate-fondant'].includes(r.id))return chefFoodArt(r,step);return r.steps.slice(0,step).filter(s=>!AUTOMATIC_STEPS[s]).map((s,i)=>`<span class="dish-layer ${s==='Plate'?'dish-plate':'dish-food'}" style="--layer:${i}">${objectArt(s)}</span>`).join('');}

function chefFoodArt(r,step){
 const done=r.steps.slice(0,step),has=s=>done.includes(s),finished={'pizza':'Finished pizza','pasta':'Finished pasta','mushroom-melt':'Finished melt'};
 if(step===r.steps.length)return `<span class="dish-layer dish-plate">${objectArt(finished[r.id])}</span>`;
 const vessel=r.steps[0];let result=`<span class="dish-layer dish-plate">${objectArt(vessel)}</span>`;
 if(r.id==='pizza'){
 if(has('Pizza dough'))result+=`<span class="pizza-base">${objectArt('Pizza dough')}</span>`;
 if(has('Tomato sauce'))result+='<i class="pizza-sauce"></i>';
 if(has('Mozzarella'))result+='<span class="pizza-cheese">'+Array.from({length:8},(_,i)=>`<i style="--i:${i}"></i>`).join('')+'</span>';
 if(has('Bake pizza'))return `<span class="dish-layer dish-plate">${objectArt('Finished pizza')}</span>`;
 }else if(r.id==='pasta'){
 if(has('Hot water')&&!has('Drain pasta'))result+='<i class="pot-water"></i>';
 if(has('Penne'))result+=`<span class="pan-contents ${has('Tomato sauce')?'sauced':''}">${objectArt('Penne')}</span>`;
 if(has('Simmer sauce'))return `<span class="dish-layer dish-plate">${objectArt('Finished pasta')}</span>`;
 }else{
 if(has('Mushrooms'))result+=`<span class="pan-contents">${objectArt('Mushrooms')}</span>`;
 if(has('Bread'))result+=`<span class="pan-contents">${objectArt('Bread')}</span>`;
 if(has('Cheese'))result+=`<span class="pan-contents cheese-layer">${objectArt('Cheese')}</span>`;
 if(has('Grill melt'))return `<span class="dish-layer dish-plate">${objectArt('Finished melt')}</span>`;
 }return result;
}

function luxuryFoodArt(r,step){
 const has=s=>r.steps.slice(0,step).includes(s),finished={'truffle-risotto':'Finished risotto','lobster-pasta':'Finished lobster','chocolate-fondant':'Finished fondant'};
 if(step===r.steps.length)return `<span class="dish-layer dish-plate">${objectArt(finished[r.id])}</span>`;
 const vessel=has('Fine plate')?'Fine plate':has('Ramekin')?'Ramekin':r.steps[0];
 let art=`<span class="dish-layer dish-plate">${objectArt(vessel)}</span>`;
 if(r.id==='truffle-risotto'&&has('Arborio rice'))art+=`<span class="luxury-contents">${objectArt('Arborio rice')}</span>`;
 if(r.id==='lobster-pasta'&&has('Penne'))art+=`<span class="luxury-contents">${objectArt('Penne')}</span>`;
 if(r.id==='lobster-pasta'&&has('Cooked lobster'))art+=`<span class="lobster-topping">${objectArt('Cooked lobster')}</span>`;
 if(r.id==='chocolate-fondant'&&has('Dark chocolate'))art+=has('Melt chocolate')?'<i class="chocolate-batter"></i>':`<span class="luxury-contents">${objectArt('Dark chocolate')}</span>`;
 return art;
}
